(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');let ticking=false;function update(){ticking=false;const y=window.scrollY,max=document.documentElement.scrollHeight-innerHeight;document.documentElement.style.setProperty('--page-progress',max>0?Math.max(0,Math.min(1,y/max)):0);document.documentElement.style.setProperty('--hero-shift',reduce.matches?0:Math.min(28,y*.08));document.documentElement.style.setProperty('--hero-opacity',reduce.matches?1:Math.max(.3,1-y/750))}addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);reduce.addEventListener('change',update);update();if(!('IntersectionObserver'in window)||reduce.matches)return;const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}},{threshold:.06});function register(){document.querySelectorAll('.path-section,.workspace-heading,.card,.code-card,.notice').forEach(e=>{if(e.dataset.motion)return;e.dataset.motion='true';e.classList.add('reveal');observer.observe(e)})}register();new MutationObserver(register).observe(document.getElementById('content'),{childList:true,subtree:true});})();
